package com.booksyde.service; import com.booksyde.dto.request.*; import com.booksyde.dto.response.*; import com.booksyde.entity.*; import com.booksyde.exception.*; import com.booksyde.repository.*; import java.util.*; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class CommunityService {private final CommentRepository comments;private final ReviewRepository reviews; public CommunityService(CommentRepository c,ReviewRepository r){comments=c;reviews=r;} @Transactional(readOnly=true) public List<CommentResponse> comments(UUID manga,UUID volume){var l=volume==null?comments.findAllByMangaIdAndVolumeIdIsNullOrderByCreatedAtDesc(manga):comments.findAllByMangaIdAndVolumeIdOrderByCreatedAtDesc(manga,volume);return l.stream().map(this::cm).toList();} @Transactional public CommentResponse addComment(Jwt j,UUID manga,CommentRequest r){return cm(comments.save(new CommentEntity(manga,r.volumeId(),uid(j),r.body().trim())));} @Transactional public CommentResponse editComment(Jwt j,UUID id,CommentRequest r){var e=comments.findById(id).orElseThrow(()->new ResourceNotFoundException("Comentário não encontrado.")); if(!e.getUserId().equals(uid(j)))throw new ForbiddenException("Sem permissão para editar este comentário.");e.setBody(r.body().trim());return cm(e);} @Transactional public void deleteComment(Jwt j,UUID id){var e=comments.findById(id).orElseThrow(()->new ResourceNotFoundException("Comentário não encontrado."));if(!e.getUserId().equals(uid(j)))throw new ForbiddenException("Sem permissão para remover este comentário.");comments.delete(e);} @Transactional(readOnly=true) public List<ReviewResponse> reviews(UUID manga){return reviews.findAllByMangaIdOrderByCreatedAtDesc(manga).stream().map(this::rv).toList();} @Transactional public ReviewResponse saveReview(Jwt j,UUID manga,ReviewRequest r){UUID u=uid(j);var e=reviews.findByUserIdAndMangaId(u,manga).orElseGet(()->new ReviewEntity(manga,u,r.rating(),r.body()==null?"":r.body().trim()));e.update(r.rating(),r.body()==null?"":r.body().trim());return rv(reviews.save(e));} @Transactional public void deleteReview(Jwt j,UUID manga){reviews.findByUserIdAndMangaId(uid(j),manga).ifPresent(reviews::delete);} private UUID uid(Jwt j){return UUID.fromString(j.getSubject());} private CommentResponse cm(CommentEntity e){return new CommentResponse(e.getId(),e.getMangaId(),e.getVolumeId(),e.getUserId(),e.getBody(),e.getCreatedAt());} private ReviewResponse rv(ReviewEntity e){return new ReviewResponse(e.getId(),e.getMangaId(),e.getUserId(),e.getRating(),e.getBody(),e.getCreatedAt());}}